Translate("esMX", "death-s-head", {
	title = "Galponmuerte",
	aliases = { "tribu Galponmuerte", "culto Galponmuerte" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Galponmuerte son los sumos sacerdotes de los {link:quilboar}jabaespines{/link}, guardianes de los cementerios de {link:razorfen-downs}la Zahúrda{/link} Rajacieno. Se han vuelto hacia la {link:scourge}Plaga{/link}. Bajo el liche {link:amnennar-the-coldbringer}Amnennar the Coldbringer{/link}, sirven a la no-muerte en el lugar más sagrado de su pueblo, y muchos de sus guerreros caminan ahora como cadáveres marchitos.]=],
		},
		{
			title = "El pacto",
			text = [=[Nadie fuera de {link:razorfen-downs}la Zahúrda{/link} conoce toda la verdad de cómo empezó. La {link:scourge}Plaga{/link} envió a un emisario, el embajador {link:ambassador-malcin}Malcin{/link}, que ofreció a los jabaespines {link:the-barrens}Los Baldíos{/link} y más a cambio de su ayuda. {link:varimathras}Varimathras{/link} cree que la vieja del {link:razorfen-kraul}Horado Rajacieno{/link} se mantuvo al margen del trato. Los sacerdotes de la Zahúrda no. Algunos de su tribu se han vuelto temiblemente fuertes y muestran las marcas de la peste. La elfa de la noche {link:myriam-moonsinger}Myriam Moonsinger{/link} vio a jabaespines salir a hurtadillas de las sombras cada día para suplicar más poder al emisario.]=],
		},
		{
			title = "La orden",
			text = [=[Sacerdotes, nigromantes, geomantes y cultistas Galponmuerte sirven al liche junto a guerreros jabaespines vivos y tejespinas. {link:quilboar}Jabaespines{/link} marchitos, jabalíes de batalla y esqueletos llenan sus filas. Entre ellos están {link:ragglesnout}Ragglesnout{/link}, que aún vive, y {link:plaguemaw-the-rotting}Plaguemaw el Putrefacto{/link}, que no. Sus cautivos se guardan en corrales cerca de la puerta, y los que no son rescatados son quemados y devorados ante el ídolo.]=],
		},
	},
})
